// Dynamically fetch secrets from AWS Secrets Manager
async function loadSecrets() {
  try {
    const databaseUrl = await secretsManager.getSecretValue({ SecretId: 'DATABASE_URL' }).promise();
    const awsKey = await secretsManager.getSecretValue({ SecretId: 'AWS_ACCESS_KEY_ID' }).promise();
    return { databaseUrl: databaseUrl.SecretString, awsKey: awsKey.SecretString };
  } catch (err) {
    console.error('Failed to load secrets:', err);
    process.exit(1);
  }
}

// Example route using secrets
app.get('/secure-data', async (req, res) => {
  const secrets = await loadSecrets();
  console.log('Database URL:', secrets.databaseUrl); // Use securely
  res.json({ message: 'Secure data accessed' });
});

// Health route
