  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Error handling
app.use((err, req, res, next) => {
  console.error('Error:', err.stack);
  res.status(500).send('Internal Server Error');
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

---

### Key Takeaways
- **Do not rely on `.env` files** for production secrets.
- Use a **secrets manager** to fetch credentials dynamically.
- Ensure test credentials (like those in `.env.test`) are **synthetic** and never exposed in production.
- Validate environment variables if they are used temporarily.

